          "source": "netlist",
          "quote": "(net (name \"HSE_IN_FCC\") ... (node (ref \"FCC1\") (pin \"5\") (pinfunction \"PE6\")) (node (ref \"HSE1\") (pin \"1\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"HSE_OUT_FCC\") ... (node (ref \"FCC1\") (pin \"37\") (pinfunction \"PE7\"))"
        },
